result:
.list{
	padding: 20px 0 1px 0;
	.item{
		width: 315px;
		height: 102px;
		background: #F5F5F5;
		border-radius: 6px;
		margin: 0 0 20px 20px;
		padding: 0 20px 0 24px;
		border: 1px solid #F5F5F5;
		cursor: pointer;
		&:hover{
			background: rgba(44,139,239,0.1);
			border-color: #2D8CF0;
		}
		.iconfont{
			font-size: 50px;
			color: #2D8CF0;
		}
		.text{
			margin-left: 13px;
			color: #999999;
			font-size: 12px;
			width: 205px;
			.name{
				color: #333333;
				font-size: 16px;

			}
		}
	}
}
.header{
	height: 44px;
	border-bottom: 1px solid #F5F5F5;
	padding: 0 20px;
	line-height: 44px;
	font-size: 12px;
	color: #333;
	.title{
		font-size: 14px;
		font-weight: 600;
		margin-right: 9px;
	}
}
